BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, email text NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member')), status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,email));
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL, owner_user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,owner_user_id) REFERENCES users(tenant_id,id));
CREATE TABLE project_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, user_id uuid NOT NULL, membership_role text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,project_id,user_id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, invoice_number text NOT NULL, project_id uuid NOT NULL, amount numeric(14,2) NOT NULL, currency char(3) NOT NULL, status text NOT NULL, issued_at timestamptz NOT NULL, due_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,invoice_number), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id));
CREATE TABLE invoice_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, description text NOT NULL, quantity numeric(12,3) NOT NULL, unit_price numeric(14,2) NOT NULL, amount numeric(14,2) NOT NULL, UNIQUE(tenant_id,invoice_id,description), FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, owner_type text NOT NULL CHECK(owner_type IN ('project','invoice')), owner_id uuid NOT NULL, original_filename text NOT NULL, content_type text NOT NULL, object_key text NOT NULL UNIQUE, object_version_id text, content_size bigint NOT NULL CHECK(content_size>=0), sha256 char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION enforce_attachment_owner_tenant() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.owner_type='project' THEN IF NOT EXISTS(SELECT 1 FROM projects WHERE tenant_id=NEW.tenant_id AND id=NEW.owner_id) THEN RAISE EXCEPTION 'attachment project owner does not belong to tenant'; END IF; ELSIF NEW.owner_type='invoice' THEN IF NOT EXISTS(SELECT 1 FROM invoices WHERE tenant_id=NEW.tenant_id AND id=NEW.owner_id) THEN RAISE EXCEPTION 'attachment invoice owner does not belong to tenant'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER attachments_owner_tenant BEFORE INSERT OR UPDATE OF tenant_id,owner_type,owner_id ON attachments FOR EACH ROW EXECUTE FUNCTION enforce_attachment_owner_tenant();
CREATE TABLE activity_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, actor_user_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,actor_user_id) REFERENCES users(tenant_id,id));
CREATE TABLE export_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), requested_by uuid NOT NULL, idempotency_key text, request_hash char(64) NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','available','failed','canceled','expired')), attempt_count int NOT NULL DEFAULT 0, max_attempts int NOT NULL DEFAULT 3, lease_owner text, lease_expires_at timestamptz, progress_phase text NOT NULL DEFAULT 'queued', record_count bigint NOT NULL DEFAULT 0, attachment_count bigint NOT NULL DEFAULT 0, bytes_written bigint NOT NULL DEFAULT 0, archive_object_key text, archive_sha256 char(64), manifest_sha256 char(64), verification_status text, failure_code text, failure_message text, requested_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz, expires_at timestamptz, canceled_at timestamptz, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,requested_by) REFERENCES users(tenant_id,id));
CREATE UNIQUE INDEX export_jobs_idempotency ON export_jobs(tenant_id,requested_by,idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX export_jobs_claim ON export_jobs(status,requested_at) WHERE status='queued';
CREATE INDEX export_jobs_expiry ON export_jobs(expires_at) WHERE status='available';
CREATE INDEX users_tenant_created ON users(tenant_id,created_at,id);
CREATE INDEX projects_tenant_created ON projects(tenant_id,created_at,id);
CREATE INDEX project_members_tenant_project ON project_members(tenant_id,project_id,user_id);
CREATE INDEX invoices_tenant_created ON invoices(tenant_id,created_at,id);
CREATE INDEX invoice_items_tenant_invoice ON invoice_items(tenant_id,invoice_id,id);
CREATE INDEX attachments_tenant_owner ON attachments(tenant_id,owner_type,owner_id,id);
CREATE INDEX activity_events_tenant_time ON activity_events(tenant_id,occurred_at,id);
CREATE TABLE audit_events(id bigserial PRIMARY KEY, tenant_id uuid, actor_user_id uuid, action text NOT NULL, resource_id uuid, outcome text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
